input.command:
cd /app/data; python3 - <<'EOF'
import json,base64,collections,re
rs=[json.loads(l) for l in open('DocumentReference.ndjson') if json.loads(l).get('subject')]
lines=collections.Counter()
for r in rs:
    t=base64.b64decode(r['content'][0]['attachment']['data']).decode()
    for ln in t.split('\n'):
        ln=ln.strip()
        if ln: lines[re.sub(r'\d+','#',ln)]+=1
for k,v in lines.most_common():
    if v<=40: print(v,'|',k)
EOF

