import json,collections
want=collections.Counter()
for l in open('Observation.ndjson'):
    o=json.loads(l)
    for cc in o.get('code',{}).get('coding',[]):
        d=(cc.get('display') or '').lower()
        if 'inr' in d or 'prothrombin' in d or 'magnesium' in d or d=='potassium':
            want[(cc.get('code'),cc.get('display'),o.get('effectiveDateTime','')[:4])]+=1
for k,v in sorted(want.items()): print(k,v)
EOF

