    for x in cond[pid]:
        for cc in x['code']['coding']:
            d=(cc.get('display') or '')
            if any(k in d.lower() for k in KW):
                cl[(cc.get('code'),d)].add((encdate(x.get('encounter',{}).get('reference','')),x['id']))
